import { afterEach, beforeEach, expect, test } from "bun:test";
import { countOrders, db } from "./db";

beforeEach(() => {
	db.run("BEGIN");
});

afterEach(() => {
	db.run("ROLLBACK");
});

test("saves an order", () => {
	db.run("INSERT INTO orders (id, total) VALUES (1, 30)");
	expect(countOrders()).toBe(1);
});

test("starts with no orders", () => {
	expect(countOrders()).toBe(0);
});

