import { expect, test } from "bun:test";
import { app } from "./app";
import { db } from "./db";

test("POST /orders stores the order", async () => {
	const response = await app.fetch(
		new Request("http://localhost/orders", {
			method: "POST",
			body: JSON.stringify({ productId: 7, quantity: 2 }),
		}),
	);

	expect(response.status).toBe(201);
	const row = db.query("SELECT quantity FROM orders WHERE product_id = 7").get();
	expect(row).toEqual({ quantity: 2 });
});

